import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { emphasisCSS } from './Emphasis.sty.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { StylingProps } from '../core/types/styling-props.js';
import type { WithChildren } from '../core/types/with-children.js';

export interface EmphasisProps extends WithChildren, StylingProps, DataTestId {}

/**
 * The `Emphasis` component adds visual and semantic emphasis to stressed or essential content.
 */
export const Emphasis = /* @__PURE__ */ forwardRef<HTMLElement, EmphasisProps>(
  (props, ref) => {
    const {
      children,
      'data-testid': dataTestId,
      className: consumerClassName,
      style: consumerStyle,
      ...remainingProps
    } = props;

    return (
      <em
        ref={ref}
        data-testid={dataTestId}
        className={clsx(emphasisCSS, consumerClassName)}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </em>
    );
  },
);

(Emphasis as typeof Emphasis & { displayName: string }).displayName =
  'Emphasis';
